PROFILES = {p.name:p for p in (PUBLIC_016,LOCAL_020)}

def validate_inventory(profile, migrations, tables):
    require(type(profile) is SourceProfile and PROFILES.get(profile.name)==profile)
    require(type(migrations) is list and sorted(tuple(row) for row in migrations)==sorted(profile.migrations))
    require(type(tables) is list and len(tables)==len(set(tables)) and sorted(tables)==sorted(profile.tables))
    return profile

