def validate_identity_inventory(profile,tables,enums):
    require(type(profile) is IdentityProfile and profile==LOGTO_145)
    require(type(tables) is list and sorted(tables)==list(profile.tables))
    require(type(enums) is list and enums==[[name,list(labels)] for name,labels in profile.enums])
    return profile

# Derived only from fresh owned DBs initialized with the exact public migration
# bytes above / pinned official Logto image. Owner/ACL identities remain separate
# raw before/during/after observations; logical DDL is a fixed profile boundary.
CATALOG_PINS = {'local_001_020': 'ba0329188d974882a77c08ffb42b6a97d2f81b335d99e8d9e6b296e976794ee8', 'logto-1.45.0': '7de09d75386c7e5f802c192aa2592b82ed68d2b9bcc6852b6dbdccd368c0af27', 'public_001_016': 'e066a74e85dc85b1263e3b6537549a04c0f1a9b024758b464b1903af87fc500d'}

def profile_catalog_digest(catalog):
    from .bundles import canonical_bytes
    require(type(catalog) is dict)
    public=lambda rows:[row for row in rows if row[0]=='public']
    value={
      'columns':[row[:3]+row[5:] for row in public(catalog['columns'])],
      'constraints':[row for row in public(catalog['constraints']) if row[:3]!=['public','credit_lots','b2_media_lot_commit']],
      'functions':[row[:4] for row in public(catalog['functions'])],
      'enums':catalog['enums'],
      'indexes':public(catalog['indexes']),
      'policies':public(catalog['policies']),
      'triggers':[row for row in public(catalog['triggers']) if row[2] not in {'a_b2_rows','a_b2_truncate','b2_media_lot_commit'}],
      'types':[[row[0],row[1],row[2],row[5]] for row in public(catalog['types'])],
      'relation_options':public(catalog['relation_options']),
      'sequence_definitions':public(catalog['sequence_definitions']),
      'rules':public(catalog['rules']),
      'operators':public(catalog['operators']),
      'collations':public(catalog['collations']),
      'casts':catalog['casts'],
      'extensions':catalog['extensions'],
      'event_triggers':catalog['event_triggers'],
    }
    return hashlib.sha256(canonical_bytes(value)).hexdigest()

def validate_profile_catalog(profile,catalog):
    from .contracts import B2Error
    require(type(profile) in {SourceProfile,IdentityProfile})
    require((type(profile) is SourceProfile and PROFILES.get(profile.name)==profile) or profile==LOGTO_145)
    try:
        require(profile.name in CATALOG_PINS and profile_catalog_digest(catalog)==CATALOG_PINS[profile.name])
    except (KeyError,IndexError,TypeError,ValueError,AttributeError):
        raise B2Error() from None
    return catalog
